import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { CBURNETT_IMAGES, CHECKERS_IMAGES, MERIDA_IMAGES } from '../pieceAssets';

/**
 * THE BUNDLED PIECE FILES (command #27d). A phone drew the Merida black king and queen in the white pieces' look while every base64 data URI was right in a browser; the three image themes are now
 * 36 real files that Metro bundles (assets/pieces/<theme>/<key>.png), generated byte for byte from src/data/pieceSets.json. What is pinned here: every theme resolves 12 DIFFERENT files, the white
 * and the black piece of a kind are different files, the 36 are all different, none is a data URI, the registry's imports are literal (Metro needs that), and the generator says the files
 * are in sync with the JSON. Every expectation is a literal. The pixels of each file are pieceThemes.test.ts's.
 */
const root = process.cwd();
const KEYS = ['wk', 'wq', 'wr', 'wb', 'wn', 'wp', 'bk', 'bq', 'br', 'bb', 'bn', 'bp'];
const KINDS = ['k', 'q', 'r', 'b', 'n', 'p'];
const SETS: Record<string, Record<string, unknown>> = { cburnett: CBURNETT_IMAGES, merida: MERIDA_IMAGES, checkers: CHECKERS_IMAGES };
const fileOf = (source: unknown) => path.join(root, String(source));
const sha = (source: unknown) => readFileSync(fileOf(source)).toString('base64');

describe.each(['cburnett', 'merida', 'checkers'])('the bundled set %s', (theme) => {
  const set = SETS[theme];

  it('has exactly the twelve keys, each a real file in assets/pieces/<theme>/ (not a data URI)', () => {
    expect(Object.keys(set).sort()).toEqual([...KEYS].sort());
    for (const key of KEYS) {
      expect(String(set[key]).startsWith('data:'), key).toBe(false);
      expect(existsSync(fileOf(set[key])), key).toBe(true);
      expect(String(set[key]), key).toBe(`/assets/pieces/${theme}/${key}.png`);
    }
    expect(readdirSync(path.join(root, 'assets', 'pieces', theme)).sort()).toEqual(KEYS.map((key) => `${key}.png`).sort());
  });

  it('is twelve DIFFERENT files, and the white and the black piece of every kind are different files', () => {
    expect(new Set(KEYS.map((key) => set[key])).size).toBe(12);
    expect(new Set(KEYS.map((key) => sha(set[key]))).size).toBe(12);
    for (const kind of KINDS) {
      expect(set['w' + kind], kind).not.toBe(set['b' + kind]);
      expect(sha(set['w' + kind]), kind).not.toBe(sha(set['b' + kind]));
    }
  });

  it('every file is a PNG (the 8-byte signature) of 120 x 120', () => {
    for (const key of KEYS) {
      const bytes = readFileSync(fileOf(set[key]));
      expect([...bytes.subarray(0, 8)], key).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
      expect([bytes.readUInt32BE(16), bytes.readUInt32BE(20)], key).toEqual([120, 120]);
    }
  });
});

describe('the three bundled sets together', () => {
  it('are 36 different files: no piece of one theme is the file of another', () => {
    const all = Object.values(SETS).flatMap((set) => KEYS.map((key) => set[key]));
    expect(all).toHaveLength(36);
    expect(new Set(all).size).toBe(36);
    expect(new Set(all.map(sha)).size).toBe(36);
  });

  it('the registry source imports every file by a literal path (Metro resolves nothing computed) and holds no data URI', () => {
    const source = readFileSync(path.join(root, 'src', 'logic', 'pieceAssets.ts'), 'utf8');
    const imports = source.match(/^import \w+ from '\.\.\/\.\.\/assets\/pieces\/(cburnett|merida|checkers)\/[wb][kqrbnp]\.png';$/gm) ?? [];
    expect(imports).toHaveLength(36);
    expect(source).not.toContain('data:');
    expect(source).not.toContain('require(');
  });

  it('the generator reports every file and the registry in sync with src/data/pieceSets.json', () => {
    const out = execFileSync(process.execPath, [path.join(root, 'scripts', 'generate-piece-assets.mjs'), '--check'], { encoding: 'utf8' });
    expect(out).toContain('in sync');
  });

  it('no built-in piece image reaches a screen as a data URI: pieceThemes.ts imports the registry and not the JSON', () => {
    const source = readFileSync(path.join(root, 'src', 'logic', 'pieceThemes.ts'), 'utf8');
    expect(source).toContain("from './pieceAssets'");
    expect(source).not.toMatch(/^import .*pieceSets/m);
  });
});
